 "content": "def transform(grid):
    n = len(grid)
    out = [[0] * (3 * n) for _ in range(3 * n)]
    # Tile each occupied input cell by its color, expanding its position into
    # a 3x3 marker representing its local diagonal orientation.
    for r in range(n):
        for c in range(n):
            v = grid[r][c]
            if not v:
                continue
            # The demonstration shows each input cell generates a 2x2 corner
            # motif, oriented by the source color's local marker: here all
            # occupied cells use the upper-left 2x2 corner-pair pattern.
            for dr, dc in ((0, 0), (0, 1), (1, 0), (1, 1)):
                out[3*r + dr][3*c + dc] = v
    return out
"
}

